@Service
public class WarrantyService 
		extends BaseService {
//************************************************************************
// Public Methods
//************************************************************************
	/**
	 * Default Constructor
	 */
    public WarrantyService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new WarrantyEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(WarrantyRepository.class) );
		this.validator		= applicationContext.getBean(WarrantyValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		Warranty
	 */
		public Warranty createWarranty( CreateWarrantyCommand command ) {

		Warranty entity = new Warranty();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setWarrantyId( command.getWarrantyId() );
            entity.setCoverageMonths( command.getCoverageMonths() );
            entity.setWarrantyType( command.getWarrantyType() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of Warranty {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateWarrantyCommand
	 * @return		Warranty
	 */
	public Warranty updateWarranty( UpdateWarrantyCommand command ) {

		Warranty entity = new Warranty();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setWarrantyId( command.getWarrantyId() );
            entity.setCoverageMonths( command.getCoverageMonths() );
            entity.setAircraft( command.getAircraft() );
            entity.setWarrantyType( command.getWarrantyType() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of Warranty {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeleteWarrantyCommand
	 */
	public void delete( DeleteWarrantyCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getWarrantyId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of Warranty {0} ", id );

	}

	/**
	 * Method to retrieve the Warranty via WarrantyFetchOneSummary
	 * @param 	summary WarrantyFetchOneSummary
	 * @return 	WarrantyFetchOneResponse
	 */
	public Warranty getWarranty( WarrantyFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "WarrantyFetchOneSummary arg cannot be null" );

		Warranty entity = null;
		UUID id = summary.getWarrantyId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a Warranty using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all Warrantys
	 *
	 * @return 	List<Warranty>
	 */
    public List<Warranty> getAllWarranty() {
		List<Warranty> list = projector.findAll( new FindAllWarrantyQuery() );
		return list;
	}

	/**
	 * assign Aircraft on Warranty
	 * @param		command AssignAircraftToWarrantyCommand
	 */
	public void assignAircraft( AssignAircraftToWarrantyCommand command ) {
		// --------------------------------------
		// best to validate the command now
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.assignAircraft(command.getWarrantyId(), command.getAssignment());

	}

	/**
	 * unAssign Aircraft on Warranty
	 * @param		command UnAssignAircraftFromWarrantyCommand
	 */
	public void unAssignAircraft( UnAssignAircraftFromWarrantyCommand command ) {

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.unAssignAircraft(command.getWarrantyId());
	}
	




//************************************************************************
// Attributes
//************************************************************************
	@Autowired
    private final WarrantyEntityProjector projector;
	private final WarrantyValidator validator;
	private Warranty warranty 	= null;
	private CurrentIdentity identity			= null;
	private static final Logger LOGGER 			=  LoggerFactory.getLogger(WarrantyService.class);
}
